package cn.zhuatech.kms.controller; import cn.zhuatech.kms.common.ApiResponse; import cn.zhuatech.kms.dto.KmsDto.*; import cn.zhuatech.kms.service.KmsService; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/admin") @PreAuthorize("hasAnyRole('KNOWLEDGE_MANAGER','QUALITY','ADMIN')") public class KnowledgeAdminController {private final KmsService service;public KnowledgeAdminController(KmsService service){this.service=service;}@GetMapping("/dashboard") public ApiResponse<Dashboard> dashboard(){return ApiResponse.ok(service.adminDashboard());}@GetMapping("/work-orders") public ApiResponse<List<KnowledgeArticleView>> orders(){return ApiResponse.ok(service.knowledgeArticles());}}
